local HourglassMaker = {}
local PRODUCTS = {
    small_hourglass = { name = "Majhna peščena ura", glassCost = 1, sandCost = 1, woodCost = 1, time = 2, cost = 20, precision = 50, description = "Majhna peščena ura za 15 minut." },
    brass_hourglass = { name = "Medeninasta peščena ura", glassCost = 1, sandCost = 1, brassCost = 1, time = 3, cost = 50, precision = 65, prestige = 2, description = "Medeninasta peščena ura za učenjake." },
    silver_hourglass = { name = "Srebrna peščena ura", glassCost = 1, sandCost = 1, silverCost = 1, time = 5, cost = 120, precision = 78, prestige = 5, happiness = 1, description = "Srebrna peščena ura za plemiče." },
    silver_frame_hourglass = { name = "Srebrno okvirna peščena ura", glassCost = 1, sandCost = 1, silverCost = 1, goldCost = 1, time = 8, cost = 300, precision = 88, prestige = 11, happiness = 2, description = "Peščena ura v srebrnem okvirju za visoke plemiče." },
    gold_trim_hourglass = { name = "Zlatorobna peščena ura", glassCost = 1, sandCost = 1, goldCost = 1, jewelCost = 1, silverCost = 1, time = 11, cost = 680, precision = 94, prestige = 18, happiness = 4, description = "Zlatorobna peščena ura z draguljem." },
    royal_grand_hourglass = { name = "Kraljevski veliki peščena ura", glassCost = 2, sandCost = 2, goldCost = 2, silverCost = 1, jewelCost = 1, pearlCost = 1, time = 16, cost = 1800, precision = 100, prestige = 40, happiness = 8, description = "Velika kraljevska peščena ura z zlatom in dragulji za kronanje." },
}
local BUILDINGS = {
    workshop = { name = "Peščenourška delavnica", cost = { gold = 260, wood = 130, stone = 200 }, upkeep = 6, qualityBonus = 5 },
    glass_blowing_room = { name = "Steklopihačnica", cost = { gold = 900, wood = 250, stone = 450, glass = 8 }, upkeep = 22, qualityBonus = 18 },
    calibration_room = { name = "Kalibrirnica", cost = { gold = 2200, wood = 350, stone = 700, silver = 30, sand = 8 }, upkeep = 55, qualityBonus = 30 },
    royal_hourglass_atelier = { name = "Kraljevski atelje peščenih ur", cost = { gold = 9000, wood = 600, stone = 1000, gold = 60, jewel = 20 }, upkeep = 180, qualityBonus = 55, prestigeBonus = 40 },
}
HourglassMaker.glassStock = 12; HourglassMaker.sandStock = 18; HourglassMaker.woodStock = 14; HourglassMaker.brassStock = 10; HourglassMaker.silverStock = 8; HourglassMaker.goldStock = 6; HourglassMaker.jewelStock = 6; HourglassMaker.pearlStock = 4
HourglassMaker.productStock = {}; HourglassMaker.buildings = {}; HourglassMaker.maker = nil; HourglassMaker.activeMaking = {}; HourglassMaker.totalProducts = 0; HourglassMaker.dayTimer = 0
function HourglassMaker.init() HourglassMaker.glassStock=12; HourglassMaker.sandStock=18; HourglassMaker.woodStock=14; HourglassMaker.brassStock=10; HourglassMaker.silverStock=8; HourglassMaker.goldStock=6; HourglassMaker.jewelStock=6; HourglassMaker.pearlStock=4; HourglassMaker.productStock={}; HourglassMaker.buildings={}; HourglassMaker.maker=nil; HourglassMaker.activeMaking={}; HourglassMaker.totalProducts=0; HourglassMaker.dayTimer=0; print("[HourglassMaker] Royal Hourglass Maker System initialized (6 products, 4 buildings)") end
function HourglassMaker.hireMaker(n,s) s=s or math.random(50,90); local c=500+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; HourglassMaker.maker={name=n or ("Peščenurar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Peščenurar najet: %s (spretnost: %d)",HourglassMaker.maker.name,s),"success") end; return true end
function HourglassMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function HourglassMaker.build(id) local ok,e=HourglassMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(HourglassMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function HourglassMaker.getQualityBonus() local b=0; for _,bd in ipairs(HourglassMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function HourglassMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.glassCost and HourglassMaker.glassStock<(d.glassCost or 0) then return false,"Premalo stekla" end; if d.sandCost and HourglassMaker.sandStock<(d.sandCost or 0) then return false,"Premalo peska" end; if d.woodCost and HourglassMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.brassCost and HourglassMaker.brassStock<(d.brassCost or 0) then return false,"Premalo medenine" end; if d.silverCost and HourglassMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and HourglassMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and HourglassMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and HourglassMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #HourglassMaker.buildings==0 then return false,"Potrebna delavnica" end; if not HourglassMaker.maker then return false,"Potreben peščenurar" end; return true end
function HourglassMaker.make(pt,qty) qty=qty or 1; local ok,e=HourglassMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.glassCost then HourglassMaker.glassStock=HourglassMaker.glassStock-d.glassCost*qty end; if d.sandCost then HourglassMaker.sandStock=HourglassMaker.sandStock-d.sandCost*qty end; if d.woodCost then HourglassMaker.woodStock=HourglassMaker.woodStock-d.woodCost*qty end; if d.brassCost then HourglassMaker.brassStock=HourglassMaker.brassStock-d.brassCost*qty end; if d.silverCost then HourglassMaker.silverStock=HourglassMaker.silverStock-d.silverCost*qty end; if d.goldCost then HourglassMaker.goldStock=HourglassMaker.goldStock-d.goldCost*qty end; if d.jewelCost then HourglassMaker.jewelStock=HourglassMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then HourglassMaker.pearlStock=HourglassMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if HourglassMaker.maker then t=math.max(1,t-math.floor(HourglassMaker.maker.skill/12)) end; table.insert(HourglassMaker.activeMaking,{id="hourglass_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,precision=d.precision or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function HourglassMaker.completeMaking(m) local q=1.0+(HourglassMaker.getQualityBonus()/100); if HourglassMaker.maker then q=q+(HourglassMaker.maker.skill/180) end; q=math.min(2.0,q); HourglassMaker.productStock[m.productType]=(HourglassMaker.productStock[m.productType] or 0)+m.quantity; HourglassMaker.totalProducts=HourglassMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if HourglassMaker.maker then HourglassMaker.maker.itemsMade=HourglassMaker.maker.itemsMade+m.quantity; if math.random()<0.20 then HourglassMaker.maker.skill=math.min(100,HourglassMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Peščena ura izdelana: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"hourglass.completed",{productName=m.productName,precision=m.precision}) end end
function HourglassMaker.update(dt) if not _G.state then return end; HourglassMaker.dayTimer=HourglassMaker.dayTimer+dt; if HourglassMaker.dayTimer>=30 then HourglassMaker.dayTimer=0; for i=#HourglassMaker.activeMaking,1,-1 do local m=HourglassMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then HourglassMaker.completeMaking(m); table.remove(HourglassMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(HourglassMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if HourglassMaker.maker then tu=tu+13 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function HourglassMaker.getStats() return {glassStock=HourglassMaker.glassStock,sandStock=HourglassMaker.sandStock,woodStock=HourglassMaker.woodStock,brassStock=HourglassMaker.brassStock,silverStock=HourglassMaker.silverStock,goldStock=HourglassMaker.goldStock,jewelStock=HourglassMaker.jewelStock,pearlStock=HourglassMaker.pearlStock,productStock=HourglassMaker.productStock,numBuildings=#HourglassMaker.buildings,hasMaker=HourglassMaker.maker~=nil,makerName=HourglassMaker.maker and HourglassMaker.maker.name or "—",makerSkill=HourglassMaker.maker and HourglassMaker.maker.skill or 0,activeMaking=#HourglassMaker.activeMaking,totalProducts=HourglassMaker.totalProducts} end
return HourglassMaker
